/bin/bash -lc "python - <<'PY'
import sim
s=sim.Sim()
for obj,typ in [(sim.mujoco.mjtObj.mjOBJ_SITE,'site'),(sim.mujoco.mjtObj.mjOBJ_BODY,'body'),(sim.mujoco.mjtObj.mjOBJ_GEOM,'geom')]:
    names=[]
    # iterate max maybe small
    n=getattr(s.model, {'mjOBJ_SITE':'nsite','mjOBJ_BODY':'nbody','mjOBJ_GEOM':'ngeom'}[str(typ)])
    # can't map str keys; do direct
    if obj==sim.mujoco.mjtObj.mjOBJ_SITE:
        n=s.model.nsite
    elif obj==sim.mujoco.mjtObj.mjOBJ_BODY:
        n=s.model.nbody
    else:
        n=s.model.ngeom
    for i in range(n):
        nm=sim.mujoco.mj_id2name(s.model,obj,i)
        if nm:
            names.append(nm)
    print('\\n'+typ,'count',n,'non-empty',len(names))
    for nm in names:
        if any(k in nm.lower() for k in ['hand','panda','finger','gripper','tcp','ee','wrist','site','tip','finger']):
            print(' ',nm)
    # print few relevant maybe all if under 80
    if len(names)<=120:
        for nm in names:
            if nm not in [x for x in ['floor','table_top','cabinet_left','cabinet_right','cabinet_back','cabinet_bottom','cabinet_top','drawer_bottom','drawer_back','drawer_left','drawer_right','drawer_front','drawer_handle','block','block_geom']]:
                pass
# print all actuator names with ranges already above and joint names
print('\\nbodies full:')
for i in range(s.model.nbody):
    nm=sim.mujoco.mj_id2name(s.model, sim.mujoco.mjtObj.mjOBJ_BODY, i)
    if nm and any(w in nm.lower() for w in ['panda','robotiq','hand','lbr','l_f','r_f','left','right','finger']):
        print(i,nm)
print('\\ngrasp site/joint?')
for i in range(s.model.njnt):
    nm=sim.mujoco.mj_id2name(s.model, sim.mujoco.mjtObj.mjOBJ_JOINT, i)
    if nm and ('finger' in nm or 'joint' in nm):
        print(i,nm,s.model.jnt_range[i])
